//! The in-memory graph.
use self::node::Node;
use crate::util;

pub mod node;

pub struct Graph {
    nodes: Vec<Node>,
}

impl Graph {
    pub fn new() -> Self {
        Graph { nodes: Vec::new() }
    }

    pub fn add(&mut self, node: Node) {
        self.nodes.push(node);
    }

    pub fn is_empty(&self) -> bool {
        util::count(self.nodes.len()) == 0
    }
}

